<?php
/* Musicband PWA ICON: ressources PNG existantes embarquées sans modification. */
/* Sert une icône PNG préparée par web/site.py à partir des ressources embarquées.
 * Le marqueur des icônes encodées est remplacé lors de la préparation ; aucun accès aux données métier.
 */
$icons=json_decode(base64_decode('',true),true);$key=$_GET['size']??'192';
if(!is_string($key)||!isset($icons[$key])){http_response_code(404);exit;}
header('Content-Type: image/png');header('Cache-Control: public,max-age=86400');header('X-Content-Type-Options: nosniff');echo base64_decode($icons[$key],true);
